db:bulk-insert.db:bulk-input-parameters:
#[vars.raised map {
                        alert_id: $.alert_id, kind: $.kind, customer_id: $.customer_id, code: $.code,
                        announcement_id: $.announcement_id, score: $.score, reasons: $.reasons_json, raised_on: $.raised_on}]

set-payload.value:
#[output application/json --- {
            raised: vars.raised map {alertId: $.alert_id, customerId: $.customer_id, code: $.code, announcementId: $.announcement_id, score: $.score},
            alreadyKnown: sizeOf(vars.existing)}]

db:select.db:sql:
select t.trade_id, t.code, i.name as instrument_name, t.side, t.qty, t.price, to_char(t.trade_date, 'YYYY-MM-DD') as trade_date
                    from max.trades t join max.instruments i using (code)
                    where t.customer_id = :cid order by t.trade_date desc, t.trade_id desc limit 10

set-payload.value:
#[output application/json --- if (isEmpty(payload)) {found: false, step: 'new'} else {
            found: true, contextId: payload[0].context_id, alertId: payload[0].alert_id, step: payload[0].step,
            recommendation: payload[0].recommendation, memo: payload[0].memo}]

set-variable.value:
#[if (isEmpty(vars.alert)) {found: false, decided: false, status: null, title: null, label: 'Alert'}
            else do {
                var a = vars.alert[0]
                ---
                {found: true, decided: vars.decisions contains a.status, status: a.status, label: 'Alert',
                 title: a.alert_id ++ ' ' ++ a.kind ++ ': ' ++ a.customer_name ++ ' / ' ++ a.instrument_name ++ ' (' ++ (a.score as String) ++ ' 点)'}}]
